package ru.folio.notes;

import java.awt.*;
import java.awt.geom.*;
import java.awt.image.BufferedImage;
import java.io.File;
import java.util.Random;
import javax.imageio.ImageIO;

public final class MarkerTests {
    static int assertions;static final Random random=new Random(1510);
    static void check(boolean yes,String label){if(!yes)throw new AssertionError(label);assertions++;}
    static Ink.Pt pt(float x,float y,float angle){return new Ink.Pt(x,y,1,0,angle);}
    static Ink.Stroke marker(float width,Ink.Pt... points){Ink.Stroke s=new Ink.Stroke();s.tool="marker";s.width=width;java.util.Collections.addAll(s.points,points);return s;}
    static final class Outline implements InkGeometry.Sink {
        final Path2D.Float path=new Path2D.Float(Path2D.WIND_NON_ZERO);int pieces,ellipses;
        public void ellipse(float x,float y,float rx,float ry,float angle){ellipses++;}
        public void quad(float ax,float ay,float bx,float by,float cx,float cy,float dx,float dy){path.moveTo(ax,ay);path.lineTo(bx,by);path.lineTo(cx,cy);path.lineTo(dx,dy);path.closePath();pieces++;}
    }
    static Outline outline(Ink.Stroke s){Outline result=new Outline();InkGeometry.sweep(s,result);return result;}
    static void footprint(){for(float width:new float[]{.2f,1,8,22,80})for(int angle=0;angle<36;angle++){float a=(float)(angle*Math.PI/18);Ink.Stroke s=marker(width,pt(100,100,a));InkGeometry.Tip t=InkGeometry.tip(s,s.points.get(0)),pressure=InkGeometry.tip(s,new Ink.Pt(100,100,.02f,1.5f,a));check(t.rx==width/2&&t.ry==width/5&&t.angle==s.points.get(0).angle,"flat rectangular tip proportions and roll");check(t.rx==pressure.rx&&t.ry==pressure.ry,"marker width ignores pressure and tilt");Outline shape=outline(s);check(shape.ellipses==0&&shape.pieces==1,"stationary marker is one rectangular stamp");for(int j=0;j<50;j++){float x=(random.nextFloat()-.5f)*width*1.6f,y=(random.nextFloat()-.5f)*width*1.6f,c=(float)Math.cos(a),sn=(float)Math.sin(a);float wx=100+x*c-y*sn,wy=100+x*sn+y*c;boolean expected=Math.abs(x)<width/2&&Math.abs(y)<width/5;if(Math.abs(Math.abs(x)-width/2)<.0001||Math.abs(Math.abs(y)-width/5)<.0001)continue;check(shape.path.contains(wx,wy)==expected,"rotated rectangle matches analytical footprint");}}
        Ink.Stroke dot=marker(80,pt(100,100,0));Outline o=outline(dot);check(o.path.contains(61,85),"rectangular stamp retains square corner outside old round tip");check(!o.path.contains(100,130),"stamp no longer extends below narrow rectangle");check(dot.hit(139,115,0)&&!dot.hit(100,130,0),"eraser hit test follows rectangle instead of old round stroke");check(dot.hit(100,117,2)&&!dot.hit(100,119,2),"eraser circle clips against flat edge");Ink.Stroke far=marker(80,pt(-500000,800000,0));check(far.hit(-500000,800000,0)&&!far.hit(-500000,800030,0),"rectangular hit stays stable at distant coordinates");check(!InkGeometry.markerHit(marker(80),0,0,2),"empty marker has no hit");System.out.println("PASS rectangular stamps, sharp corners, roll, constant pressure-independent width and exact eraser overlap");}
    static void sweeps(){Ink.Stroke horizontal=marker(40,pt(100,100,0),pt(1100,100,0));Outline h=outline(horizontal);for(int x=81;x<1120;x++){check(h.path.contains(x,93)&&h.path.contains(x,107),"sparse horizontal marker has continuous flat width");check(!h.path.contains(x,110),"horizontal marker is not round-width pen");}check(h.ellipses==0&&h.pieces<10,"geometry cost independent of spatial gap");Ink.Stroke turn=marker(40,pt(100,100,(float)Math.toRadians(359)),pt(1100,100,(float)Math.toRadians(1)));check(outline(turn).pieces<12,"barrel rotation across zero takes short arc");Ink.Stroke spin=marker(40,pt(100,100,0),pt(1100,100,1.57f),pt(1100,600,3));Outline o=outline(spin);for(int x=101;x<1100;x++)check(o.path.contains(x,100),"rotating sparse marker has no gaps");for(int y=101;y<600;y++)check(o.path.contains(1100,y),"turning marker has no holes");for(int i=0;i<400;i++){float x=random.nextFloat()*1200,y=random.nextFloat()*700;check(spin.hit(x,y,0)==o.path.contains(x,y),"marker hit matches production swept polygon");}Ink.Stroke stationary=marker(40,pt(100,100,0),pt(100,100,1.57f));check(outline(stationary).path.contains(100,100),"stationary rotation keeps ink filled");System.out.println("PASS sparse continuous flat paths, sharp direction changes, stationary rotation, short angular interpolation and swept eraser hit");}
    static void recognized(){Ink.Stroke s=marker(20);for(int i=0;i<=80;i++)s.points.add(pt(100+i*5,100+(float)Math.sin(i*.1)*2,.7f));ShapeRecognizer.Result shape=ShapeRecognizer.recognize(s,1);check(shape!=null,"held marker line recognized");check(shape.stroke.tool.equals("marker"),"shape keeps marker opacity and tool");for(Ink.Pt p:shape.stroke.points)check(Math.abs(p.angle-.7f)<.001,"shape keeps current chisel orientation");System.out.println("PASS recognized marker shape retains flat tool and current angle");}
    static void preview(File file)throws Exception{BufferedImage image=new BufferedImage(900,420,BufferedImage.TYPE_INT_RGB);Graphics2D g=image.createGraphics();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);g.setColor(new Color(0xfffefb));g.fillRect(0,0,900,420);g.setColor(new Color(0x30364b));g.setFont(new Font("SansSerif",Font.BOLD,24));g.drawString("Плоский маркер · прямоугольный наконечник",28,40);String[] labels={"Касание","Горизонтальный след","Вертикальный след","Вращение пера"};for(int i=0;i<4;i++){int x=110+i*220;g.setComposite(AlphaComposite.SrcOver);g.setColor(new Color(0x69758c));g.setFont(new Font("SansSerif",Font.PLAIN,14));g.drawString(labels[i],x-82,80);Ink.Stroke s;if(i==0)s=marker(80,pt(x,175,0));else if(i==1)s=marker(70,pt(x-70,175,0),pt(x+70,175,0));else if(i==2)s=marker(70,pt(x,125,0),pt(x,280,0));else {s=marker(60);for(int j=0;j<=60;j++)s.points.add(pt(x-70+j*2.2f,175+(float)Math.sin(j*.06)*50,j*.035f));}g.setColor(new Color(0xcbaa46));g.setComposite(AlphaComposite.SrcOver.derive(70/255f));g.fill(outline(s).path);}g.setComposite(AlphaComposite.SrcOver);g.setColor(new Color(0x737b8b));g.setFont(new Font("SansSerif",Font.PLAIN,13));g.drawString("Модель из InkGeometry. Не снимок экрана Android.",28,390);g.dispose();ImageIO.write(image,"png",file);}
    public static void main(String[] args)throws Exception{footprint();sweeps();recognized();preview(new File(args[0]));System.out.println("PASS: "+assertions+" marker assertions");}
}
